.product-card h2 {
  padding: 0.75rem 1rem 0;
  font-size: 1rem;
}

.product-card p {
  padding: 0.25rem 1rem 1rem;
  color: #666;
}

.product-image {
  width: 100%;
  aspect-ratio: 4 / 3;
}

.product-detail {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  align-items: start;
}

.product-hero {
  width: 100%;
  aspect-ratio: 1;
  border-radius: 12px;
}

.product-info h1 {
  font-size: 2rem;
}

.product-price {
  font-size: 1.5rem;
  font-weight: 600;
  margin: 0.5rem 0;
}

.product-description {
  color: #666;
  line-height: 1.6;
}

.back-link {
  display: inline-block;
  margin-bottom: 1.5rem;
  color: #666;
  text-decoration: none;
}

.skeleton-image {
  background: #e5e5e5;
  animation: pulse 1.5s ease-in-out infinite;
}

